/**
 * Ícone decorativo. Aceita "nome" ou "bi-nome". Mantém a tag <i> para o CSS existente.
 *
 * @param string $nome
 * @return string
 */
function site_icone(string $nome): string
{
    $nome   = preg_replace('/^bi-/', '', $nome);
    $icones = site_icones();

    if (!isset($icones[$nome])) {
        return '';
    }

    return '<i class="bi bi-' . esc_attr($nome) . '" aria-hidden="true">'
        . '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" fill="currentColor" focusable="false">' . $icones[$nome] . '</svg>'
        . '</i>';
}
